(x, y, t) => {
  const wx = x + Math.sin(y * 0.02 + t * 0.3) * 20 + Math.sin(y * 0.05 - t * 0.7) * 8;
  const wy = y + Math.cos(x * 0.02 - t * 0.4) * 20 + Math.cos(x * 0.05 + t * 0.6) * 8;
  const src = [
    [120 + Math.sin(t*0.7)*80, 60 + Math.cos(t*0.5)*40, 0.09, 2.1, 1.0],
    [360 + Math.cos(t*0.6)*80, 180 + Math.sin(t*0.8)*40, 0.11, 1.8, 0.9],
    [240 + Math.sin(t*0.4+2)*120, 120 + Math.cos(t*0.6+1)*70, 0.07, 2.5, 1.1],
    [80 + Math.cos(t*0.9+3)*60, 180 + Math.sin(t*0.3+2)*50, 0.13, 1.5, 0.8],
    [400 + Math.sin(t*0.5+4)*70, 50 + Math.cos(t*0.7+3)*60, 0.08, 2.3, 1.0]
  ];
  let act = 0, inh = 0;
  for (const [sx, sy, freq, spd, amp] of src) {
    const d = Math.sqrt((wx-sx)**2 + (wy-sy)**2);
    act += Math.sin(d*freq - t*spd) * amp;
    inh += Math.sin(d*freq*0.4 - t*spd*0.7) * amp;
  }
  act /= src.length; inh /= src.length;
  const ms1 = Math.sin(wx*0.06+wy*0.04+t*0.9), ms2 = Math.sin(wx*0.04-wy*0.06+t*1.2);
  const ms3 = Math.sin((wx+wy)*0.12+t*2.8)*0.2, ms4 = Math.sin((wx-wy)*0.1-t*2.2)*0.2;
  const ms5 = Math.sin(wx*0.02+t*0.5)*Math.sin(wy*0.025-t*0.4);
  const globInhib = (ms1+ms2+ms5)/3;
  let reaction = act - globInhib*0.9 + ms3+ms4;
  reaction += Math.sin(act*3.14)*0.15;
  const rd = Math.tanh(reaction*2.8);
  const cx = 240, cy = 120, dist = Math.sqrt((wx-cx)**2+(wy-cy)**2);
  const ang = Math.atan2(wy-cy, wx-cx);
  const spiral = Math.sin(dist*0.05-ang*3-t*1.2);
  const petals = Math.sin(ang*5+t*0.6)*Math.sin(dist*0.03-t*0.8);
  const layer2 = Math.tanh((spiral+petals*0.6)*2.2);
  const rings = Math.sin(dist*0.08-t*2)*Math.sin(dist*0.06+t*1.5);
  const blend = rd*0.5+layer2*0.3+Math.tanh(rings*1.5)*0.2;
  const v = blend*0.5+0.5;
  const pal = [[15,12,58],[22,42,122],[22,136,122],[225,180,55],[215,95,75],[140,35,65],[15,12,58]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const sf = f*f*(3-2*f);
  const lum = 0.88+Math.sin(reaction*Math.PI)*0.12;
  const vignette = 1-Math.pow(dist/300,2)*0.25;
  const bright = lum*vignette;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*bright)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*bright)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*bright)|0
  ];
}
